    self.save_platform = sys.platform
    for input, output in (('2.4.3 (#1, Jun 21 2006, 13:54:21) \n[GCC 3.3.4 (pre 3.3.5 20040809)]', ('CPython', '2.4.3', '', '', '1', 'Jun 21 2006 13:54:21', 'GCC 3.3.4 (pre 3.3.5 20040809)')), ('2.4.3 (truncation, date, t) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', 'date t', 'GCC')), ('2.4.3 (truncation, date, ) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', 'date', 'GCC')), ('2.4.3 (truncation, date,) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', 'date', 'GCC')), ('2.4.3 (truncation, date) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', 'date', 'GCC')), ('2.4.3 (truncation, d) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', 'd', 'GCC')), ('2.4.3 (truncation, ) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', '', 'GCC')), ('2.4.3 (truncation,) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', '', 'GCC')), ('2.4.3 (truncation) \n[GCC]', ('CPython', '2.4.3', '', '', 'truncation', '', 'GCC'))):
        name, version, branch, revision, buildno, builddate, compiler = platform._sys_version(input)
        assert (name, version, '', '', buildno, builddate, compiler) == output, ('assertEqual', (name, version, '', '', buildno, builddate, compiler), output)
    sys_versions = {('2.6.1 (r261:67515, Dec  6 2008, 15:26:00) \n[GCC 4.0.1 (Apple Computer, Inc. build 5370)]', ('CPython', 'tags/r261', '67515'), self.save_platform): ('CPython', '2.6.1', 'tags/r261', '67515', ('r261:67515', 'Dec  6 2008 15:26:00'), 'GCC 4.0.1 (Apple Computer, Inc. build 5370)'), ('3.10.8 (tags/v3.10.8:aaaf517424, Feb 14 2023, 16:28:12) [GCC 9.4.0]', None, 'linux'): ('CPython', '3.10.8', '', '', ('tags/v3.10.8:aaaf517424', 'Feb 14 2023 16:28:12'), 'GCC 9.4.0'), ('2.5 (trunk:6107, Mar 26 2009, 13:02:18) \n[Java HotSpot(TM) Client VM ("Apple Computer, Inc.")]', ('Jython', 'trunk', '6107'), 'java1.5.0_16'): ('Jython', '2.5.0', 'trunk', '6107', ('trunk:6107', 'Mar 26 2009'), 'java1.5.0_16'), ('2.5.2 (63378, Mar 26 2009, 18:03:29)\n[PyPy 1.0.0]', ('PyPy', 'trunk', '63378'), self.save_platform): ('PyPy', '2.5.2', 'trunk', '63378', ('63378', 'Mar 26 2009'), '')}
    for (version_tag, scm, sys_platform), info in sys_versions.items():
        sys.version = version_tag
        if scm is None:
            if hasattr(sys, '_git'):
                del sys._git
        else:
            sys._git = scm
        if sys_platform is not None:
            sys.platform = sys_platform
        assert platform.python_implementation() == info[0], ('assertEqual', platform.python_implementation(), info[0])
        assert platform.python_version() == info[1], ('assertEqual', platform.python_version(), info[1])
        assert platform.python_branch() == info[2], ('assertEqual', platform.python_branch(), info[2])
        assert platform.python_revision() == info[3], ('assertEqual', platform.python_revision(), info[3])
        assert platform.python_build() == info[4], ('assertEqual', platform.python_build(), info[4])
        assert platform.python_compiler() == info[5], ('assertEqual', platform.python_compiler(), info[5])
    try:
        platform._sys_version('2. 4.3 (truncation) \n[GCC]')
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
